// 修补单词
fixword = func(test_items, test_words, indexs, mapped1, mapped2) {
    for i in indexs {
        item = test_words[i]
        star_index = item.Find("*")
        cipher_char = test_items[i][star_index:star_index+1]
        item_len = len(item)
        b = false
        for c = ord("a"); c <= ord("z"); c++ {
            if mapped2[c] == "*" {
                word = item.ReplaceAll("*", chr(c))
                if word in words[item_len] {
                    mapped1[ord(cipher_char)] = chr(c)
                    mapped2[c] = cipher_char
                    test_words[i] = word
                    b = true
                }
            }
        }
        if !b {
            test_words[i] = item.ReplaceAll("*", "?")
        }
    }
}

// 将密文与单词进行匹配
matchword = func(ii, test_items, item, word, mapped1, mapped2, matches, info) {
    item_len = len(item)
    for i = 0; i < item_len; i++ {
        item_int = ord(item[i:i+1])
        word_int = ord(word[i:i+1])
        if mapped1[item_int] == "*" {
            if mapped2[word_int] != "*" {
                return
            } else {
                mapped1[item_int] = word[i:i+1]
                mapped2[word_int] = item[i:i+1]
            }
        } else if mapped1[item_int] != word[i] {
            return
        }
    }

    matchitem(ii+1, test_items, mapped1, mapped2, matches + [word], info)
}

// 通过映射关系渲染内容
rendercontent = func(content, mapped1) {
    result = ""
    for c in content.Lower() {
        if c >= "a" && c <= "z" {
            result += mapped1[ord(c)]
        } else {
            result += c
        }
    }
    return result
}

renderlist = func(items, mapped1) {
    content = " ".Join(items)
    result = rendercontent(content, mapped1)
    return result.Split(" ")
}

countChar = func(str, char) {
    count = 0
    for i = 0; i < len(str); i++ {
        if str[i] == char {
            count++
        }
    }
    return count
}

// 获取只含有一个*的单词索引
get_one_star_word_index = func(test_words) {
    indexs = []
    for i = 0; i < len(test_words); i++ {
        item = test_words[i]
        if countChar(item, "*") == 1 {
            indexs += [i]
        }
    }
    indexs.Reverse()
    return indexs
}

// 匹配密文项
matchitem = func(ii, test_items, mapped1, mapped2, matches, info) {
    if ii < len(test_items) {
        item = test_items[ii]
        for word in words[len(item)] {
            if word in matches {
                continue
            }
            //println(ii, item, word, matches)
            matchword(ii, test_items, item, word, mapped1 + [], mapped2 + [], matches, info)
        }
    } else {
        temp_indexs = []
        for true {
            test_words = renderlist(info["sorted_items"], mapped1)
            indexs = get_one_star_word_index(test_words)
            if len(indexs) > 0 && string(indexs) != string(temp_indexs) {
                fixword(info["sorted_items"], test_words, indexs, mapped1, mapped2)
                temp_indexs = indexs
            } else {
                break
            }
        }

        parsed = renderlist(info["sorted_items"], mapped1)
        content_parsed = rendercontent(info["content"], mapped1)
        num = 0
        mw = ""
        for item in parsed {
            if item in words[len(item)] {
                num += 1
                mw += item + " "
            }
        }

        if num > info["best_num"] {
            info["best_num"] = num
            info["best_mapped"] = mapped1
            info["best_parsed"] = parsed
            info["best_content_parsed"] = content_parsed
            info["best_matched_words"] = mw
        }

        if num == info["best_num"] && mw != info["best_matched_words"] {
            println("=================================================================")
            println("映射关系为：")
            printmapped(mapped1)
            println("匹配单词量：" + num)
            println("匹配单词为：" + mw)
            println("解密结果为：" + content_parsed)
        }
    }
}

// 打印映射关系
printmapped = func(mapped1) {
