randNums = func(min_num, max_num, count) {
    result = []
    if min_num >= max_num {
        return []
    }
    if count > max_num - min_num {
        count = max_num - min_num
    }
    for len(result) < count {
        num = randn(min_num, max_num)
        if num in result {
            continue
        }else {
            result.Append(num)
        }
    }
    return result
}

unique = func(arr) {
    result = []
    for item in arr {
        if item in result {
            continue
        }else {
            result.Append(item)
        }
    }
    return result
}

// 按字符串长度升序排序（短→长）
sortByLength = func(arr) {
    n = len(arr)
    for i = 0; i < n-1; i++ {
        for j = 0; j < n-i-1; j++ {
            if len(arr[j]) > len(arr[j+1]) {
                // 交换元素
                temp = arr[j]
                arr[j] = arr[j+1]
                arr[j+1] = temp
            }
        }
    }
    return arr
}

